package links

import (
	"fmt"
	"math"
	"slices"
	"time"
)

// maxNetemJitter is the highest jitter the kernel accepts without capping it.
const maxNetemJitter = math.MaxInt32 * time.Nanosecond

// maxNetemRate is the highest rate in kbit/s that can be converted to bytes/s.
const maxNetemRate = math.MaxUint64 / 1000

// NetemRaw is the link impairment of an endpoint as defined in the topology file.
// It applies to the packets the endpoint's interface sends.
type NetemRaw struct {
	Delay      string  `yaml:"delay,omitempty"`
	Jitter     string  `yaml:"jitter,omitempty"`
	Loss       float64 `yaml:"loss,omitempty"`
	Rate       uint64  `yaml:"rate,omitempty"`
	Corruption float64 `yaml:"corruption,omitempty"`
}

// Netem is the resolved link impairment of an endpoint.
type Netem struct {
	Delay      time.Duration
	Jitter     time.Duration
	Loss       float64
	Rate       uint64
	Corruption float64
}

// Resolve validates the impairment and returns nil if it sets nothing.
func (r *NetemRaw) Resolve() (*Netem, error) {
	if r == nil {
		return nil, nil
	}

	netem := &Netem{Loss: r.Loss, Rate: r.Rate, Corruption: r.Corruption}

	var err error
	if netem.Delay, err = parseNetemDuration("delay", r.Delay); err != nil {
		return nil, err
	}
	if netem.Jitter, err = parseNetemDuration("jitter", r.Jitter); err != nil {
		return nil, err
	}

	if netem.Jitter != 0 && netem.Delay == 0 {
		return nil, fmt.Errorf("netem jitter cannot be set without setting delay")
	}
	if netem.Jitter > maxNetemJitter {
		return nil, fmt.Errorf("netem jitter must be at most %s", maxNetemJitter)
	}
	if !(netem.Loss >= 0 && netem.Loss <= 100) {
		return nil, fmt.Errorf("netem loss must be in the range between 0 and 100")
	}
	if !(netem.Corruption >= 0 && netem.Corruption <= 100) {
		return nil, fmt.Errorf("netem corruption must be in the range between 0 and 100")
	}

	if netem.Rate > maxNetemRate {
		return nil, fmt.Errorf("netem rate must be at most %d kbit/s", uint64(maxNetemRate))
	}

	if *netem == (Netem{}) {
		return nil, nil
	}

	return netem, nil
}

func parseNetemDuration(name, value string) (time.Duration, error) {
	if value == "" {
		return 0, nil
	}

	duration, err := time.ParseDuration(value)
	if err != nil {
		return 0, fmt.Errorf("netem %s %q is not a duration, e.g. 100ms: %w", name, value, err)
	}
	if duration < 0 {
		return 0, fmt.Errorf("netem %s %q must not be negative", name, value)
	}

	return duration, nil
}

func declaresNetem(e *EndpointRaw) bool {
	return e != nil && e.Netem != nil && *e.Netem != (NetemRaw{})
}

// checkNetemOnVeth rejects link impairments on the endpoints of a link that is not a veth link.
func checkNetemOnVeth(lt LinkType, endpoints ...*EndpointRaw) error {
	if slices.ContainsFunc(endpoints, declaresNetem) {
		return fmt.Errorf("netem is only supported on veth links, not on %s links", lt)
	}

	return nil
}

// DeclaresNetem reports whether the link sets a link impairment on any of its endpoints.
func (ld *LinkDefinition) DeclaresNetem() bool {
	var endpoints []*EndpointRaw

	switch l := ld.Link.(type) {
	case *LinkVEthRaw:
		endpoints = l.Endpoints
	case *LinkVEthStitchedRaw:
		endpoints = l.Endpoints
	case *LinkHostRaw:
		endpoints = []*EndpointRaw{l.Endpoint}
	case *LinkMacVlanRaw:
		endpoints = []*EndpointRaw{l.Endpoint}
	case *LinkMgmtNetRaw:
		endpoints = []*EndpointRaw{l.Endpoint}
	case *LinkDummyRaw:
		endpoints = []*EndpointRaw{l.Endpoint}
	case *LinkVxlanRaw:
		endpoints = []*EndpointRaw{&l.Endpoint}
	}

	return slices.ContainsFunc(endpoints, declaresNetem)
}

package links

import (
	"context"
	"fmt"
	"slices"
	"strings"
	"sync"

	"github.com/charmbracelet/log"
	clabconstants "github.com/srl-labs/containerlab/constants"
	clabutils "github.com/srl-labs/containerlab/utils"
	"github.com/vishvananda/netlink"
)

// LinkVEthRaw is the raw (string) representation of a veth link as defined in the topology file.
type LinkVEthRaw struct {
	LinkCommonParams `               yaml:",inline"`
	Endpoints        []*EndpointRaw `yaml:"endpoints"`
	fromBrief        bool
}

// ToLinkBriefRaw converts the raw link into a LinkBriefRaw.
func (r *LinkVEthRaw) ToLinkBriefRaw() *LinkBriefRaw {
	lc := &LinkBriefRaw{
		Endpoints:        []string{},
		LinkCommonParams: r.LinkCommonParams,
	}

	for _, e := range r.Endpoints {
		lc.Endpoints = append(lc.Endpoints, fmt.Sprintf("%s:%s", e.Node, e.Iface))
	}

	if slices.ContainsFunc(r.Endpoints, func(e *EndpointRaw) bool { return e.Netem != nil }) {
		for _, e := range r.Endpoints {
			lc.Netem = append(lc.Netem, e.Netem)
		}
	}

	return lc
}

func (*LinkVEthRaw) GetType() LinkType {
	return LinkTypeVEth
}

// Resolve resolves the raw veth link definition into a Link interface that is implemented
// by a concrete LinkVEth struct.
// Resolving a veth link resolves its endpoints.
func (r *LinkVEthRaw) Resolve(params *ResolveParams) (Link, error) {
	// filtered true means the link is in the filter provided by a user
	// aka it should be resolved/created/deployed
	filtered := isInFilter(params, r.Endpoints)
	if !filtered {
		return nil, nil
	}

	if r.fromBrief && r.briefDefaultLinkType(params) == LinkTypeVethStitch {
		return NewVEthStitchedRawFromVEth(r).Resolve(params)
	}

	// create LinkVEth struct
	l := NewLinkVEth()
	l.LinkCommonParams = r.LinkCommonParams

	// Normalize link vars to ensure JSON serialization compatibility
	l.Vars = normalizeVars(l.Vars)

	// resolve raw endpoints (epr) to endpoints (ep)
	for _, epr := range r.Endpoints {
		if (epr.Node == "host" || epr.Node == "mgmt-net") && declaresNetem(epr) {
			return nil, fmt.Errorf("netem is not supported on %s endpoints", epr.Node)
		}

		ep, err := epr.Resolve(params, l)
		if err != nil {
			return nil, err
		}

		// add endpoint to the link endpoints
		l.Endpoints = append(l.Endpoints, ep)
	}

	// set default link mtu if MTU is unset
	if l.MTU == 0 {
		l.MTU = clabconstants.DefaultLinkMTU
	}

	return l, nil
}

// linkVEthRawFromLinkBriefRaw creates a raw veth link from a LinkBriefRaw.
func linkVEthRawFromLinkBriefRaw(lb *LinkBriefRaw) (*LinkVEthRaw, error) {
	host, hostIf, node, nodeIf, err := extractHostNodeInterfaceData(lb, 0)
	if err != nil {
		return nil, err
	}

	link := &LinkVEthRaw{
		LinkCommonParams: lb.LinkCommonParams,
		Endpoints: []*EndpointRaw{
			NewEndpointRaw(host, hostIf, ""),
			NewEndpointRaw(node, nodeIf, ""),
		},
	}

	// populate vars
	if err := mapBriefVarsToEndpoints(lb, link.Endpoints); err != nil {
		return nil, err
	}

	if len(lb.Netem) > len(link.Endpoints) {
		return nil, fmt.Errorf("number of netem entries exceeds the number of endpoints")
	}
	for i, netem := range lb.Netem {
		link.Endpoints[i].Netem = netem
	}

	// set default link mtu if MTU is unset
	if link.MTU == 0 {
		link.MTU = clabconstants.DefaultLinkMTU
	}

	return link, nil
}

func (r *LinkVEthRaw) cleanupFilteredLink(
	ctx context.Context,
	labName string,
	nodesFilter []string,
) error {
	if !r.fromBrief {
		return nil
	}

	// probe every brief veth because its node-selected default is
	// unavailable after filtering; non-stitched probes are harmless no-ops.
	return cleanupFilteredVethStitch(ctx, labName, nodesFilter, r.Endpoints)
}

// defaultLinkTypeProvider is a type that can provide the default link type for a node. Currently
// only needed for SR-SIM nodes that use veth-stitch for a regular veth link.
type defaultLinkTypeProvider interface {
	DefaultLinkType() LinkType
}

func (r *LinkVEthRaw) briefDefaultLinkType(params *ResolveParams) LinkType {
	for _, ep := range r.Endpoints {
		n, ok := params.Nodes[ep.Node]
		if !ok {
			continue
		}

		provider, ok := n.(defaultLinkTypeProvider)
		if !ok {
			continue
		}

		lt := provider.DefaultLinkType()
		if lt != "" && lt != LinkTypeVEth {
			return lt
		}
	}

	return LinkTypeVEth
}

type LinkVEth struct {
	LinkCommonParams
	Endpoints []Endpoint

	deployMutex sync.Mutex
}

func NewLinkVEth() *LinkVEth {
	return &LinkVEth{
		Endpoints: make([]Endpoint, 0, 2),
	}
}

func (*LinkVEth) GetType() LinkType {
	return LinkTypeVEth
}

func (l *LinkVEth) deployAEnd(ctx context.Context, idx int) error {
	ep := l.Endpoints[idx]
	// the peer Endpoint is the other of the two endpoints in the
	// Endpoints slice. So do a +1 on the index and modulo operation
	// to take care of the wrap around.
	peerIdx := (idx + 1) % 2
	peerEp := l.Endpoints[peerIdx]

	log.Debugf("Creating Endpoint: %s ( --> %s )", ep, peerEp)

	// build the netlink.Veth struct for the link provisioning
	linkA := &netlink.Veth{
		LinkAttrs: netlink.LinkAttrs{
			Name: ep.GetRandIfaceName(),
			MTU:  l.MTU,
			// Mac address is set later on
		},
		PeerName: peerEp.GetRandIfaceName(),
		// PeerMac address is set later on
	}

	// add the link
	err := netlink.LinkAdd(linkA)
	if err != nil {
		return err
	}

	// cleanup is a helper that removes the veth pair if a subsequent step fails
	// after LinkAdd succeeded, preventing orphaned interfaces from blocking retries.
	cleanup := func(err error) error {
		if delErr := netlink.LinkDel(linkA); delErr != nil {
			log.Debugf(
				"failed to cleanup veth pair %s after error: %v",
				ep.GetRandIfaceName(),
				delErr,
			)
		}
		return err
	}

	// disable TXOffloading
	if err := clabutils.EthtoolTXOff(ep.GetRandIfaceName()); err != nil {
		return cleanup(err)
	}

	// the link needs to be moved to the relevant network namespace
	// and enabled (up). This is done via linkSetupFunc.
	// based on the endpoint type the link setup function is different.
	// linkSetupFunc is executed in a netns of a node.
	// if the node is a regular namespace node
	// add link to node, rename, set mac and Up
	err = ep.GetNode().AddLinkToContainer(ctx, linkA,
		SetNameMACAndUpInterface(linkA, ep))
	if err != nil {
		return cleanup(err)
	}

	l.DeploymentState = LinkDeploymentStateHalfDeployed

	// e.g. host endpoints are nodeless, and therefore the B end of the veth link should
	// be deployed right after the A end is deployed.
	if peerEp.IsNodeless() {
		return l.deployBEnd(ctx, peerIdx)
	}

	return nil
}

func (l *LinkVEth) deployBEnd(ctx context.Context, idx int) error {
	ep := l.Endpoints[idx]
	peerEp := l.Endpoints[(idx+1)%2]

	log.Debugf("Assigning Endpoint: %s ( --> %s )", ep, peerEp)

	// retrieve the netlink.Link for the provided Endpoint
	link, err := netlink.LinkByName(ep.GetRandIfaceName())
	if err != nil {
		return err
	}

	// disable TXOffloading
	if err := clabutils.EthtoolTXOff(ep.GetRandIfaceName()); err != nil {
		return err
	}

	// Host endpoints already live in the current namespace; set them up in place.
	// Other nodeless endpoints, such as the management bridge, still need their
	// node-specific setup.
	if ep.IsNodeless() && ep.GetNode().GetLinkEndpointType() == LinkEndpointTypeHost {
		if err := SetNameMACAndUpInterface(link, ep)(nil); err != nil {
			return err
		}
	} else if err = ep.GetNode().AddLinkToContainer(ctx, link,
		SetNameMACAndUpInterface(link, ep)); err != nil {
		return err
	}

	l.DeploymentState = LinkDeploymentStateFullDeployed

	if len(l.Endpoints) == 2 {
		log.Infof("Created link: %s ▪┄┄▪ %s", l.Endpoints[0], l.Endpoints[1])
	}

	return nil
}

// getEndpointIndex returns the index of the ep endpoint belonging to l link.
// An error is returned when the ep is not part of the l's endpoints.
func (l *LinkVEth) getEndpointIndex(ep Endpoint) (int, error) {
	for idx, e := range l.Endpoints {
		if e == ep {
			return idx, nil
		}
	}

	// if the endpoint is not part of the link
	// build a string list of endpoints and return a meaningful error
	var epStrings []string
	for _, e := range l.Endpoints {
		epStrings = append(epStrings, e.String())
	}

	return -1, fmt.Errorf(
		"endpoint %s does not belong to link [ %s ]",
		ep.String(),
		strings.Join(epStrings, ", "),
	)
}

// Deploy deploys the veth link by creating the A and B sides of the veth pair independently
// based on the calling endpoint.
func (l *LinkVEth) Deploy(ctx context.Context, ep Endpoint) error {
	// since each node calls deploy on its links, we need to make sure that we only deploy
	// the link once, even if multiple nodes call deploy on the same link.
	l.deployMutex.Lock()
	defer l.deployMutex.Unlock()

	// first we need to check that the provided ep is part of this link
	idx, err := l.getEndpointIndex(ep)
	if err != nil {
		return err
	}

	// Retry transient netlink errors that can occur during concurrent link operations.
	// deployAEnd cleans up partial state on failure, making each retry idempotent.
	return retryTransientNetlink(ctx, fmt.Sprintf("deploy link %s", ep), func() error {
		switch l.DeploymentState {
		case LinkDeploymentStateHalfDeployed:
			return l.deployBEnd(ctx, idx)
		case LinkDeploymentStateFullDeployed:
			return nil
		default:
			return l.deployAEnd(ctx, idx)
		}
	})
}

func (*LinkVEth) PostDeploy(context.Context) error {
	return nil
}

func (l *LinkVEth) Remove(ctx context.Context) error {
	l.deployMutex.Lock()
	defer l.deployMutex.Unlock()
	if l.DeploymentState == LinkDeploymentStateRemoved {
		return nil
	}
	for _, ep := range l.GetEndpoints() {
		err := ep.Remove(ctx)
		if err != nil {
			log.Debug(err)
		}
	}
	l.DeploymentState = LinkDeploymentStateRemoved
	return nil
}

func (l *LinkVEth) GetEndpoints() []Endpoint {
	return l.Endpoints
}

func (l *LinkVEth) GetRuntimeEndpoints() []Endpoint {
	return l.GetEndpoints()
}

